"""Create the requested minimal development generation; preserve v0.1 code and runs."""
from pathlib import Path
import json,hashlib,datetime,shutil
ROOT=Path(__file__).resolve().parents[2];BASE=ROOT/'models/bcap'
CODE=BASE/'development_v2/v0.2.0';AN=ROOT/'columns/001-ball-count/analysis'
DAY=datetime.datetime.now().strftime('%Y%m%d');BUNDLE=AN/f'bcap_v2_development_{DAY}__r01'
def read(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def write(p,o):Path(p).write_text(json.dumps(o,ensure_ascii=False,indent=2),encoding='utf-8')
def sha(p):
 with Path(p).open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
assert not BUNDLE.exists();BUNDLE.mkdir()
CODE.mkdir(parents=True,exist_ok=True)
assert not (CODE/'engine.py').exists()
original=(BASE/'run.py').read_text(encoding='utf-8-sig')
core=original[:original.index('\ndef learn_policy')]
core=core.replace('"""BCAP v0.1.0. Existing local data only; new run directories are mandatory."""','"""V2 development numerical core reused from BCAP v0.1.0. No external/policy/bootstrap entry points."""')
core=core.replace('ROOT=Path(__file__).resolve().parents[2]','ROOT=Path(__file__).resolve().parents[4]')
core=core.replace("def cfg(model): return read(MODEL/model/'v0.1.0/specification.yaml')",'SAVE_DIR=None\ndef save_tuning_model(model,label):\n    if SAVE_DIR is not None:\n        path=Path(SAVE_DIR)/(label+\'.pkl\');path.parent.mkdir(parents=True,exist_ok=True)\n        with path.open(\'wb\') as f:pickle.dump(model,f,protocol=5)')
core=core.replace("    split_record(records,label+'/tune','tuning',fit,tune)","    if frozen_alpha is None:split_record(records,label+'/tune','tuning',fit,tune)")
core=core.replace("                pr=reg.predict(ev);truth=", "                save_tuning_model(reg,label+'/tune/'+target+'/'+str(alpha))\n                pr=reg.predict(ev);truth=")
core=core.replace('    return model,tuning',"    model.calibration_rows=cal[['row_id','game_pk','A']].copy();model.calibration_rows['raw_propensity']=r\n    model.training_games=sorted(map(int,train.game_pk.unique()));model.internal_seed=seed\n    return model,tuning")
(CODE/'engine.py').write_text(core,encoding='utf-8')
versions={'pitch':('BCAP-PITCH-v0.2.0','0.2.0'),'swing':('BCAP-SWING-v0.2.0','0.2.0'),'pitch_sb':('BCAP-PITCH-SB-v0.1.0','0.1.0')}
configs={}
for model,(mid,version) in versions.items():
 base=read(BASE/('swing' if model=='swing' else 'pitch')/'v0.1.0/specification.yaml')
 fs=[{'prev_pitch_type':'prev_pitch_group','pitch_type':'pitch_group'}.get(x,x) for x in base['features']]
 if model=='pitch_sb':fs.append('pitch_group')
 c={k:base[k] for k in ['actions','pa_exclusions','ridge_objective','solver','unknown_categories','numerical_epsilon','trim','min_entity_arm_training','min_rows','min_ess','min_arm_games','min_coverage','max_game_share','practical_delta_W']}
 c.update(model_id=mid,version=version,status_at_definition='DRAFT',variant=model,generation='V2',development_years=[2024,2025],features=fs,weights={y:base['weights'][y] for y in ['2024','2025']},action0='B' if model=='pitch_sb' else base['action0'],action1='S' if model=='pitch_sb' else base['action1'],support_entity='batter' if model=='swing' else 'pitcher',outer_folds=3,seed=20260909,comparison_family=147,alphas=[100,1000],fixed_alpha=None if model=='pitch_sb' else {'p':100,'m0':1000,'m1':1000},better='higher' if model=='swing' else 'lower')
 c.update(estimand='Associational adjusted final-PA W contrast on the same selected supported observed decision rows. Not identified intervention, sequential PA policy, or individual execution ability.',outcome='Season-weighted final PA W, no BCAI or transition reward added',s_b_definition='Finite plate_x/z/sz_top/bot and sz_top>sz_bot; S iff abs(plate_x)<=17/24 feet AND sz_bot<=plate_z<=sz_top, including boundary equality; B otherwise. Ball center at 2024/25 plate plane; no ball-radius expansion; not umpire call or intended target.',s_b_eligibility='Existing eligible_pitch AND valid geometry, retaining current known FB/NFB covariate; no current speed/movement/coordinates/Swing/outcome predictors.',lag_mapping='Known FF/SI/FC -> FB; closed permitted remainder -> NFB; START/MISSING_PREVIOUS retained; other unknown/PO codes -> UNCLASSIFIED. Stored fine codes are audit/mapping inputs only.',region='Existing INNER/BOUNDARY/OUT unchanged; BOUNDARY includes both S and B. INNER is geometric inner zone, not inside-to-batter horizontal side.',calibration='Original 5-way training-game partition, fold0 held out for Platt. Propensity refit folds1-4; outcome T-learners all training rows by arm. Train dictionaries only.',tuning='PITCH/SWING use existing development final alpha p100/m0=m1=1000 without reselection. New S/B uses only100/1000 per component, original training-game fold1 validation vsfolds2-4 fitting; ties larger alpha.',split='Original sorted unique games, RNG20260909, shuffled round-robin outer3. Per-outer nuisance seed=20260909+2000+k; calibration/tuning training-only5way. One seed, no repeated fitting beyond necessary crossfit/tuning.',policy='No policy is learned or evaluated in V2; reported direction is an evaluation-group descriptive point estimate, not d(Z). No final full-development refit needed for these OOF diagnostic tables.',uncertainty='Reused fixed-score game cluster sandwich t(G-1), individual nominal95% plus Bonferroni147 across all displayed primary delta groups; actual coverage and full-learning uncertainty unverified.',family_scope='PITCH13 + S/B13 + SWING121 =147; each overall1/count12, SWING also count-zone36/count-zone-FB-NFB72. Frequencies are descriptive. No simultaneous coverage claim for any other metric.',evidence_labels='Gate failure: 비교 자료 부족. Gate pass and Bonferroni delta interval covers0: 차이 불명확; otherwise 관찰상 방향 뚜렷. Point direction displayed separately where supported; no causal recommendation.',support='Common mask .05<=p<=.95 and entity each-arm>=30 in nuisance training; SWING also existing finite measurements/zone/known group. Group gate N500, ESS200/arm,100games/arm,coverage.5,maxgameweightshare.05.',limits=['Completed PA and final-event eligibility are post-outcome selection','Player shrinkage does not remove hidden intent/quality/confounding','SWING includes bunts and adjudicated Take/HBP; hindsight physical proxies','NFB contains FA/Other, not all physically verified non-fastballs','Known six legacy count exceptions not investigated/repaired; development includes two; retained unchanged'],not_run=['2023/2026 data access/application/external evaluation','bootstrap or repeated seed fits','independent verifier or full audit','new raw acquisition/KBO','JOINT/Nash/sequential policy','Drive/publication'])
 path=BASE/model/('v'+version);assert not path.exists();path.mkdir(parents=True)
 write(path/'specification.yaml',c)
 (path/'model_card.md').write_text(f'# {mid}\n\n상태: DRAFT. V2 2024·2025 개발 계산 준비. 별도 외부 검증·독립 검수·bootstrap은 이번 범위에서 미실시.\n',encoding='utf-8')
 (path/'validation.md').write_text('# 기본 확인 범위\n\n아직 계산 전. 기본 확인은 실행 manifest에 기록하며 별도 독립 검수와 구분한다.\n',encoding='utf-8')
 configs[model]=str((path/'specification.yaml').relative_to(ROOT))
write(BUNDLE/'design_before_results.json',dict(created_at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),request_scope='2024/2025 minimal V2 development only',specifications={m:dict(path=p,sha256=sha(ROOT/p)) for m,p in configs.items()},engine_source=dict(path='models/bcap/run.py',sha256=sha(BASE/'run.py')),engine_reuse='Core only up through cluster_stat; no policy/external/bootstrap functions. Sparse centered Ridge/Platt/AIPW formulas reused.',version_decision='PITCH/SWING minor0.2.0 for predictor changes; new pitch_sb variant starts0.1.0. V2 is generation name, not semantic major2.0.',computed_before_results=['action/features/eligibility','one3fold split and seed','fixed vs small SB alpha choices','support and effect threshold','147 multiplicity family','point vs uncertainty labels'],processed_source='columns/001-ball-count/data/processed/bcap_dev_v010_20260909_r01.pkl'))
shutil.copyfile('C:/Users/백창현/.codex/attachments/a4b329b8-b63c-418a-983e-4b3843c366fc/pasted-text.txt',BUNDLE/'request_original.txt')
print(json.dumps(dict(bundle=str(BUNDLE),configs=configs),ensure_ascii=False))
